import { renderResearchArchive } from './research-ui.js';
import { renderOriginInvitation, renderOriginArchive, renderOriginActive } from './family-origin-ui.js';
import { campaignView } from './campaign.js';
import { storyView } from './life-stories.js';
import { adventureView, contractArchive } from './adventuring.js';
import { questEntryStatus } from './quest-policy.js';
import { trackedQuest, questReturnForecast } from './quest-records.js';

const short=text=>String(text||'').split(/(?<=[.!?])\s+/).slice(0,2).join(' ');
export function renderQuestJournal(s,actions,ui,{category='main',invitations='preview',archiveQuery=''}={}) {
  const {e,button,actionCards}=ui,c=campaignView(s),stories=storyView(s),j=s.questLog;
  const status=j?.main||(s.campaign?.completed.length?'active':'offered');
  const categories=[['main','Main quests'],['side','Side quests'],['misc','Miscellaneous quests'],['radiant','Repeatable radiant quests'],['archive','Archive']];
  const nav=`<nav class="quest-categories" aria-label="Quest categories">${categories.map(([id,label])=>button(label,'quest-category',id,`ghost ${category===id?'active':''}`,false,category===id)).join('')}</nav>`;
  const command=(id,label)=>{
    const a=actions.find(a=>a.id===id);if(!a)return '';
    const days=a.durationDays??a.days??0,fee=a.quotedCost??a.cost??0;
    return `<div class="quest-command">${button(label||e(a.label),'activity',id,'secondary small',Boolean(a.disabledReason))}<small class="small-copy" data-quest-cost="${e(id)}">${days?`${days} committed ${days===1?'day':'days'}`:'No time'} · ${fee} gold fee</small>${ui.livingCosts?.(days)||''}${id.startsWith('quest_')?'<small class="small-copy">Road travel and later choices are quoted separately.</small>':''}${a.disabledReason?`<small class="disabled-reason">${e(a.disabledReason)}</small>`:''}</div>`;
  };
  const trail=arc=>`<details class="panel" data-story-record="${e(arc.id)}"><summary>${e(arc.title)} · ${e(arc.status)} · ${arc.chapter}/${arc.totalChapters} chapters</summary><p>${e(arc.personName)} · ${e(s.world.locations.find(p=>p.id===arc.locationId)?.name)} · began at age ${arc.startedAge}</p><ol class="decision-trail">${arc.choices.map((choice,index)=>`<li data-story-decision="${index+1}"><strong>Chapter ${index+1}: ${e(choice.label)}</strong><p>${e(choice.outcome)}</p><small>Day ${choice.day} · ${choice.days} committed days · ${choice.cost} gold fee · ${choice.reward} gold reward</small>${choice.consequences?`<p class="small-copy">Participant trust ${choice.consequences.bond>=0?'+':''}${choice.consequences.bond} · Local standing ${choice.consequences.standing>=0?'+':''}${choice.consequences.standing} · Professional reputation ${choice.consequences.career>=0?'+':''}${choice.consequences.career}</p>`:''}</li>`).join('')||'<li>No completed chapter decision was recorded.</li>'}</ol></details>`;
  const main=c.quests.find(q=>!q.id.startsWith('side_')&&!['completed','locked'].includes(q.status));
  let body='';
  if(category==='main')body=`<article class="panel quest-card"><div class="quest-status"><span class="badge">Main · long quest</span><span>${e(c.ending?'Completed':s.phase==='retired'&&status==='active'?'Left unfinished':status)}</span></div><h2>The Ashfall Covenant</h2><p>Trace the failing village water to an old bargain beneath the region. This optional investigation unfolds across your life.</p>${s.age<16?'<p class="muted">Childhood clues belong in your memories. Investigation opens at sixteen.</p>':c.ending?`<h3>${e(c.ending.title)}</h3><p>${e(c.ending.summary)}</p>`:status==='active'&&main?`<div class="quest-objective"><strong>Next: ${e(main.title)}</strong><p>${e(main.objective)}</p></div>${command('quest_begin_'+main.id,'Continue this objective')}${command('quest_resume_expedition','Resume expedition')}${button('Show destination','quest-location',main.locationId,'ghost small')}${command('journal_main_pause','Pause quest')}${command('journal_track_main','Track')}`:`<p class="small-copy">${status==='offered'?'A lead you may choose to follow. It has not been accepted.':'You have set this investigation aside. No unseen deadline advances it.'}</p>${command('journal_main_accept',status==='offered'?'Accept quest':'Resume quest')}${command('journal_main_decline','Decline for now')}`}${c.completedCount?`<small>${c.completedCount} objectives completed</small>`:''}</article>`;
  else if(category==='side') {
    const sides=c.quests.filter(q=>q.id.startsWith('side_')&&!['locked','completed'].includes(q.status));
    body=[['active','Accepted'],['offered','Nearby offers'],['paused','Set aside'],['declined','Declined']].map(([id,label])=>{
      const list=sides.filter(q=>questEntryStatus(s,q.id)===id);
      return list.length?`<section><h3>${label}</h3><div class="quest-grid">${list.map(q=>`<article class="panel quest-card"><span class="badge">Side quest · ${id}</span><h3>${e(q.title)}</h3><p>${e(short(q.description))}</p>${id==='active'?`<div class="quest-objective">${e(q.objective)}</div>${command('quest_'+q.id,'Continue quest')}${command('journal_pause_'+q.id,'Pause')}${command('journal_track_'+q.id,'Track')}${button('Show destination','quest-location',q.locationId,'ghost small')}`:`${command('journal_accept_'+q.id,id==='offered'?'Accept quest':'Resume quest')}${id==='offered'?command('journal_decline_'+q.id,'Decline'):''}`}</article>`).join('')}</div></section>`:'';
    }).join('');
    const offers=stories?.invitations||[],available=offers.filter(a=>a.status==='offered'),declined=offers.filter(a=>a.status==='declined');
    const shown=invitations==='all'?offers:invitations==='declined'?declined:available.slice(0,2);
    if(offers.length)body+=`<details class="panel" ${invitations!=='preview'?'open':''} data-personal-invitations data-disclosure="quest-personal-invitations"><summary>Personal stories · ${available.length} invitations${declined.length?` · ${declined.length} declined`:''}</summary><p class="small-copy">Short, optional stories. Reading this list accepts nothing. Accepting opens a proposal; you choose the days and fees afterward.</p><nav class="record-tabs" aria-label="Personal invitations">${button(`Browse all ${offers.length}`,'quest-invitations','all','ghost small',false,invitations==='all')}${button('Compact preview','quest-invitations','preview','ghost small',false,invitations==='preview')}${declined.length?button('Declined invitations','quest-invitations','declined','ghost small',false,invitations==='declined'):''}</nav><div class="quest-grid">${shown.map(offer=>`<article class="quest-card" data-invitation="${e(offer.id)}"><h3>${e(offer.title)}</h3><p><strong>${e(offer.personName)}</strong> · ${e(offer.locationName)}</p><p>${e(offer.premise)}</p>${offer.status==='declined'?`<span class="badge">Declined · never accepted</span>${command('stories_reconsider_'+offer.id,'Reconsider invitation')}`:`${command('stories_open_'+offer.id,'Accept first chapter')}${command('stories_decline_'+offer.id,'Decline invitation')}`}</article>`).join('')||'<p>No invitations in this view.</p>'}</div></details>`;
    const accepted=stories?.arcs.filter(a=>['active','paused'].includes(a.status))||[];
    if(accepted.length)body+=`<section class="panel"><h3>Stories you chose</h3>${accepted.map(arc=>`<article class="quest-card"><h3>${e(arc.title)}</h3><p>${e(arc.personName)} · ${arc.chapter}/${arc.totalChapters} chapters · ${arc.status==='paused'?'Paused':s.age<arc.nextAge?'Returns at age '+arc.nextAge:'Next chapter ready'}</p>${command('stories_open_'+arc.id,'Continue story')}${command('journal_'+(arc.status==='paused'?'resume':'pause')+'_story:'+arc.id,arc.status==='paused'?'Resume story':'Pause story')}${command('journal_track_story:'+arc.id,'Track')}${button('Show destination','quest-location',arc.locationId,'ghost small')}${trail(arc)}</article>`).join('')}${actionCards(actions.filter(a=>['stories_continue','stories_cancel'].includes(a.id)))}</section>`;
    body+=renderOriginInvitation(s,actions,ui)+renderOriginActive(s,actions,ui);
    body||='<section class="panel"><p>No side quests accepted. Meet people and visit places to discover local requests.</p></section>';
  } else if(category==='misc') {
    const due=s.obligations.filter(o=>!o.resolved);
    body=`<section class="panel"><h2>Promises &amp; small errands</h2>${due.map(o=>`<article class="misc-errand"><h3>${e(o.title)}</h3><p>${e(short(o.description))}</p><small>Due day ${o.dueDay} · ${Math.max(0,o.dueDay-s.day)} days remain</small></article>`).join('')||'<p class="muted">No outstanding promises. An obligation appears only after you agree to it.</p>'}${actionCards(actions.filter(a=>['quest_return_notes','quest_keeper_review','quest_followup','quest_civic_work','quest_memorial'].includes(a.id)))}</section>`;
    const returns=questReturnForecast(s);
    if(returns.length)body+=`<section class="panel" data-quest-calendar><h2>Returning chapters on your calendar</h2><p class="small-copy">Returns remain optional. They do not interrupt the year or accept another invitation.</p>${returns.map(row=>`<article class="misc-errand"><h3>${e(row.title)} · ${e(row.personName)}</h3><p>${row.paused?'Paused':row.ready?'Ready to revisit':`Age ${row.nextAge} · day ${row.dueDay} · ${Math.max(0,row.dueDay-s.day)} days away`}</p><p class="small-copy">Last choice: ${e(row.lastChoice)}</p>${command('journal_'+(row.paused?'resume':'pause')+'_story:'+row.id,row.paused?'Resume story':'Pause story')}</article>`).join('')}</section>`;
  } else if(category==='radiant') {
    const contracts=(adventureView(s)?.contracts||[]).filter(a=>['active','ready'].includes(a.status));
    body=`<section class="panel"><h2>Repeatable work &amp; expeditions</h2><p>Accept seasonal contracts at a settlement board. Completed and abandoned contracts retain their dated proof and receipts in Archive.</p>${contracts.map(a=>`<article class="quest-card"><span class="badge">Radiant · ${e(a.paused?'paused':a.status)}</span><h3>${e(a.title)}</h3><p>${e(short(a.brief))}</p><p class="small-copy">${a.status==='ready'?`Return to ${e(a.giver.name)} at ${e(a.board)} for payment.`:`Destination: ${e(a.destination)}.`} · ${a.reward} gold</p>${actionCards(actions.filter(cmd=>['adventure_pursue_','adventure_resolve_','adventure_claim_','adventure_abandon_'].some(prefix=>cmd.id===prefix+a.id)))}${command('journal_'+(a.paused?'resume':'pause')+'_radiant:'+a.id,a.paused?'Resume contract':'Pause contract')}${command('journal_track_radiant:'+a.id,'Track')}${button('Show destination','quest-location',a.status==='ready'?a.boardId:a.destinationId,'ghost small')}</article>`).join('')||'<p class="muted">No radiant contract accepted.</p>'}${button('Open contract board','tab','adventure','secondary')}${button('Open gear & pack','tab','inventory','ghost')}</section>`;
  } else {
    const query=String(archiveQuery).trim().toLocaleLowerCase(),matches=value=>!query||JSON.stringify(value).toLocaleLowerCase().includes(query);
    const arcs=(stories?.arcs||[]).filter(a=>!['active','paused'].includes(a.status)&&matches(a));
    const records=contractArchive(s).filter(matches),completed=c.quests.filter(q=>q.status==='completed'&&matches(q));
    body=renderResearchArchive(s,ui,{query:archiveQuery})+`<section class="panel"><h2>Quest records</h2><form id="quest-archive-search"><label class="field" for="quest-archive-query">Search records<input id="quest-archive-query" name="query" value="${e(archiveQuery)}" maxlength="120" placeholder="Title, person, place or proof"></label><button class="button secondary" type="submit">Search archive</button></form><p class="small-copy">Saved decisions and contract results remain readable after board refresh and export/reload.</p>${completed.map(q=>`<p>✓ ${e(q.title)}</p>`).join('')}${arcs.map(trail).join('')}${records.map(record=>`<details class="panel" data-contract-record="${e(record.id)}"><summary>${e(record.title)} · ${e(record.result)} · ${e(record.client)}</summary><p>${e(record.objective)}</p><p>${e(record.boardName)} → ${e(record.destinationName)}</p><p class="small-copy">${record.closedDay===null?'Closing date was not recorded in this older save':'Closed on day '+record.closedDay} · ${record.reward} gold paid</p>${record.proof?`<p>Earned ${record.proof.method?'field-work':'combat'} proof on day ${record.proof.day}${record.proof.captured?' · living captive presented':''}.</p>`:'<p>No completion proof or reward was claimed.</p>'}${record.attempts.map(a=>`<p class="small-copy">Day ${a.day}: ${a.outcome==='defeat'?'Failed combat attempt':a.outcome==='retreat'?'Withdrew from the encounter':'Encounter won'}.</p>`).join('')}</details>`).join('')}${!completed.length&&!arcs.length&&!records.length?'<p class="muted">No matching completed or abandoned accounts.</p>':''}</section>`;
    body+=renderOriginArchive(s,ui,{query:archiveQuery});
    const closed=j?.closingReview;
    if(closed)body+=`<section class="panel" data-closing-quest-record><h2>${e(closed.heroName)}’s closing account</h2><p>Day ${closed.day} · ${closed.decision==='leave_at_retirement'?'Chosen at retirement':'This life ended'}</p><p>${closed.counts.completed} completed · ${closed.counts.abandoned} abandoned · ${closed.counts.failed??0} missed or failed · ${closed.counts.paused} paused · ${closed.counts.neverAccepted} never accepted</p>${closed.unfinished.map(row=>`<p><strong>${e(row.title)}</strong> · left unfinished<br>${e(row.detail)}</p>`).join('')||'<p>No accepted quest was left unfinished.</p>'}</section>`;
  }
  const tracked=trackedQuest(s),tracking=tracked?`<aside class="quest-tracker"><span class="eyebrow">TRACKED QUEST</span><strong>${e(tracked.title)}</strong><p>${e(tracked.objective)}</p>${button('Show destination','quest-location',tracked.locationId,'ghost small')}${command('journal_clear_track','Clear tracking')}</aside>`:j?.tracked&&actions.some(a=>a.id==='journal_clear_track')?`<aside class="quest-tracker"><p>The tracked account has no active next step.</p>${command('journal_clear_track','Clear tracking')}</aside>`:'';
  const sideCount=Object.entries(j?.entries||{}).filter(([id,q])=>q.status==='active'&&s.campaign.sidequests[id.slice(5)]?.status!=='completed').length;
  return `<div class="quest-journal"><div class="section-heading"><div><span class="eyebrow">YOUR CHOSEN UNDERTAKINGS</span><h1>Journal</h1></div><span class="badge">${!c.ending&&status==='active'?1:0} main · ${sideCount} side</span></div><p class="small-copy">Accepted quests have a next step. Offers can wait. Ordinary life remains open.</p>${tracking}${nav}${body}</div>`;
}
